import{_ as n,l as i,o as e,c as m,v as t,p as l,x as r,d as p,i as c,S as s}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"连续时间 CAPM","description":"","frontmatter":{"title":"连续时间 CAPM","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/continuous-time-capm.md","filePath":"econ/continuous-time-capm.md","lastUpdated":1789023840000}'),d={name:"econ/continuous-time-capm.md"};function A(h,a,E,C,_,B){const o=i("Mermaid");return e(),m("div",null,[a[1]||(a[1]=t('<h1 id="连续时间-capm" tabindex="-1">连续时间 CAPM <a class="header-anchor" href="#连续时间-capm" aria-label="Permalink to &quot;连续时间 CAPM&quot;">​</a></h1><div class="epigraph"><p>瞬时均值–方差加同质预期、机会确定（或被市场充分代表）时，出清仍给出瞬时市场 beta 定价。</p><footer>—— Merton, An Intertemporal Capital Asset Pricing Model, Econometrica, 1973 的瞬时 CAPM 特化；对照 Sharpe–Lintner</footer></div><p><a href="/econ/hedging-demand-origin">上一课</a>在需求里加上对冲。本课缺口是出清后的定价：何时对冲项在加总里消失或被市场吸收，回到瞬时 CAPM。主干 <a href="/econ/capm-theory">CAPM 作为均衡</a> 是离散单期；本课是同一加总在连续时间的瞬时版。不估计 beta，不写 GRS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每人 \\(\\theta_i=\\) 切点 \\(+\\) 对冲。加总：市场清算切点需求；若每人的对冲能被一组可交易基金代表，再清算那些基金。机会确定：对冲为零，市场即切点，瞬时</p> \\[\\mu_i-r=\\beta_{i,m}(\\mu_m-r),\\qquad \\beta_{i,m}=\\frac{\\mathrm{Cov}(\\mathrm{d}R_i,\\mathrm{d}R_m)}{\\mathrm{Var}(\\mathrm{d}R_m)}. \\]<p>这是连续时间 CAPM。机会随机但所有 \\(z\\) 的对冲基金恰好落在市场张成里（例如单一 \\(z\\) 与市场完全相关），仍可压成单 beta。一般 ICAPM 是多 beta，主干已写。本课钉特化：瞬时、扩散、出清。</p><p><span class="marginnote">瞬时：溢价对 \\(\\mathrm{d}t\\) 的系数。有限持有期的积分溢价还含路径，不是本课。Breeden 用消费把多 beta 再压成一个，那是 CCAPM，也不在此重写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>同质预期、CRRA 或使切点相同的加总条件，连续再平衡、无摩擦。市场组合的扩散是财富加权的 \\(\\theta\\) 之和。有效性：市场瞬时均值方差有效 ⇔ 单 beta。SDF：\\(m\\) 的无穷小是 \\(1-b\\,\\mathrm{d}R_m\\)（差利率），与离散 \\(m=a-b R_m\\) 同构。资金约束课序已经指出：不能人人再平衡或不能自由借贷时，这一步失败——本课假设能。</p>',10)),(e(),l(s,null,{default:r(()=>[c(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20DET%5B%22%E6%9C%BA%E4%BC%9A%E7%A1%AE%E5%AE%9A%22%5D%20--%3E%20MKT%5B%22%E5%B8%82%E5%9C%BA%20%3D%20%E5%88%87%E7%82%B9%22%5D%0A%20%20MKT%20--%3E%20BETA%5B%22%E7%9E%AC%E6%97%B6%20%CE%BC-r%20%3D%20%CE%B2%20(%CE%BCm-r)%22%5D%0A%20%20Z%5B%22z%20%E5%8F%AF%E8%A2%AB%E5%B8%82%E5%9C%BA%E4%BB%A3%E8%A1%A8%22%5D%20--%3E%20BETA%0A%20%20Z2%5B%22%E7%8B%AC%E7%AB%8B%20z%20%E9%9C%80%E5%AF%B9%E5%86%B2%E5%9F%BA%E9%87%91%22%5D%20--%3E%20ICAPM%5B%22%E4%B8%BB%E5%B9%B2%20ICAPM%20%E5%A4%9A%20beta%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与量化栏 CAPM：那里用离散时段的超额收益回归。瞬时 beta 不是月度 beta。测量误差与区间选择是换栏的问题。本课禁止用月度 \\(R^2\\) 判决 1973。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制仍是加总后的有效性。连续时间只是让「这一瞬间的均值方差」精确等于 EU 的瞬时问题，躲过离散 MV 的二次/正态刀刃。出清把共同切点标成市场。对冲若存在且不能被市场代表，有效前沿的切点不再是市场，线性落到多因子——那是 ICAPM，不是本课的特化失败，是特化条件没满足。</p><p>信息：连续再平衡假定公共价格过程；知情者若有额外域流，他们的 \\(\\theta\\) 含投机项，市场不再是共同切点。Kyle 与 Merton 加总不要混在同一句话里。本课公共信息。</p><p><span class="marginnote">Black 的零 beta 在连续时间同样可用：关掉瞬时无风险，用与市场瞬时不相关的组合当截距。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不修补低 beta 异象。资金约束已经给出许可；实证换 <a href="/quant/capm">/quant/capm</a>。下一课把利率本身做成一般均衡对象：CIR 用生产或禀赋把 \\(r\\) 从「常数参数」变成状态变量的函数。连续时间 CAPM 把 \\(r\\) 当给定；CIR 给 \\(r\\) 一条均衡 SDE。</p><p>后课默认：瞬时 CAPM 是常机会（或市场代表全部对冲）加出清的特化。与离散 Sharpe–Lintner 同构，装置是扩散。不是横截面检验。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机会确定 + 出清 ⇒ 瞬时市场 beta 定价。</li><li>对冲能被市场张成时，仍可单 beta；否则回到 ICAPM。</li><li>连续时间许可证是瞬时 MV=EU，不是实证区间。</li><li>出处：Merton, <em>Econometrica</em> 1973；对照 <a href="/econ/capm-theory">/econ/capm-theory</a>。</li></ul>',10))])}const P=n(d,[["render",A]]);export{b as __pageData,P as default};
